import{c as a,Q as t,j as o,m as n}from"./chunks/framework.W-g_WCNV.js";const s="/screenshots/showcase-dark.gif",r="/screenshots/showcase-light.gif",i="/screenshots/login-dark.png",c="/screenshots/login-light.png",l="/screenshots/user-home-dark.png",h="/screenshots/user-home-light.png",p="/screenshots/admin-dashboard-dark.png",d="/screenshots/admin-dashboard-light.png",g="/screenshots/admin-users-dark.png",m="/screenshots/admin-users-light.png",u="/screenshots/admin-clients-dark.png",_="/screenshots/admin-clients-light.png",k="/screenshots/admin-policies-dark.png",b="/screenshots/admin-policies-light.png",y="/screenshots/admin-groups-dark.png",f="/screenshots/admin-groups-light.png",q="/screenshots/admin-audit-dark.png",w="/screenshots/admin-audit-light.png",S="/screenshots/admin-settings-dark.png",P="/screenshots/admin-settings-light.png",A="/screenshots/admin-backups-dark.png",x="/screenshots/admin-backups-light.png",E=JSON.parse('{"title":"Screenshots","description":"The GateKeeper sign-in page, user portal, and admin panel.","frontmatter":{"title":"Screenshots","description":"The GateKeeper sign-in page, user portal, and admin panel."},"headers":[],"relativePath":"screenshots.md","filePath":"screenshots.md"}'),v={name:"screenshots.md"},G=s,C=r;function D(I,e,O,T,U,K){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h1><p>GateKeeper ships light and dark themes, and remembers the choice per browser. <strong>The screenshots below follow whichever theme you are reading this page in</strong> - switch it with the toggle in the header to see the other one.</p><picture><source media="(prefers-color-scheme: dark)" srcset="'+G+'"><source media="(prefers-color-scheme: light)" srcset="'+C+'"><img class="screenshot" alt="A tour of the GateKeeper admin panel" src="'+s+'"></picture><h2 id="sign-in" tabindex="-1">Sign-in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign-in&quot;">​</a></h2><p>Password, email code, and QR code sign-in sit together in one control, with passkeys and any enabled social providers below. When an app starts the sign-in through OIDC, its name and icon replace the GateKeeper branding.</p><img class="screenshot dark-only" src="'+i+'" alt="GateKeeper sign-in page"><img class="screenshot light-only" src="'+c+'" alt="GateKeeper sign-in page"><h2 id="user-portal" tabindex="-1">User portal <a class="header-anchor" href="#user-portal" aria-label="Permalink to &quot;User portal&quot;">​</a></h2><p>Users manage their own account here: display name and avatar, sign-in methods, enrolled passkeys, and every active session with the option to sign the others out.</p><img class="screenshot dark-only" src="'+l+'" alt="User portal"><img class="screenshot light-only" src="'+h+'" alt="User portal"><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>Live sign-in activity, failed attempts, OIDC token counts, two-factor adoption, and a system health panel that surfaces anything needing attention.</p><img class="screenshot dark-only" src="'+p+'" alt="Admin dashboard"><img class="screenshot light-only" src="'+d+'" alt="Admin dashboard"><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>Create and manage accounts, approve pending registrations, promote a user to admin, and see each person&#39;s sign-in methods at a glance.</p><img class="screenshot dark-only" src="'+g+'" alt="Users page"><img class="screenshot light-only" src="'+m+'" alt="Users page"><h2 id="oidc-clients" tabindex="-1">OIDC clients <a class="header-anchor" href="#oidc-clients" aria-label="Permalink to &quot;OIDC clients&quot;">​</a></h2><p>Register the apps that delegate login to GateKeeper. Each client holds its redirect URIs, icon, custom claims, and an optional access policy.</p><img class="screenshot dark-only" src="'+u+'" alt="OIDC clients page"><img class="screenshot light-only" src="'+_+'" alt="OIDC clients page"><h2 id="access-policies" tabindex="-1">Access policies <a class="header-anchor" href="#access-policies" aria-label="Permalink to &quot;Access policies&quot;">​</a></h2><p>Policies decide who reaches which app. Attach one to an OIDC client or reference it from a ForwardAuth route, and optionally store credentials for apps that have no SSO of their own.</p><img class="screenshot dark-only" src="'+k+'" alt="Access policies page"><img class="screenshot light-only" src="'+b+'" alt="Access policies page"><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p>Group membership is published as a <code>groups</code> claim in every OIDC token, which is what apps like Grafana and Jellyfin use for role mapping.</p><img class="screenshot dark-only" src="'+y+'" alt="Groups page"><img class="screenshot light-only" src="'+f+'" alt="Groups page"><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><p>An append-only record of every authentication and admin event, filterable by category, outcome, sign-in method, and date range, and exportable as CSV.</p><img class="screenshot dark-only" src="'+q+'" alt="Audit log"><img class="screenshot light-only" src="'+w+'" alt="Audit log"><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>SMTP, session lifetime, registration mode, password policy, protected app domains, and branding. Changes apply immediately with no restart.</p><img class="screenshot dark-only" src="'+S+'" alt="Settings page"><img class="screenshot light-only" src="'+P+'" alt="Settings page"><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>Encrypted snapshots on demand or on a schedule, stored locally or in any S3-compatible bucket, and restored or uploaded from the same page.</p><img class="screenshot dark-only" src="'+A+'" alt="Backups page"><img class="screenshot light-only" src="'+x+'" alt="Backups page">',43)])])}const R=a(v,[["render",D]]);export{E as __pageData,R as default};
